import java.util.ArrayDeque;
import java.util.Deque;

public class TextEditor {
    // Left: chars left of cursor, top = adjacent to cursor.
    // Right: chars right of cursor, top = adjacent to cursor.
    private final Deque<Character> left = new ArrayDeque<>();
    private final Deque<Character> right = new ArrayDeque<>();

    public void addText(String text) {
        for (int i = 0; i < text.length(); i++) {
            left.push(text.charAt(i));
        }
    }

    public int deleteText(int k) {
        int del = 0;
        while (del < k && !left.isEmpty()) {
            left.pop();
            del++;
        }
        return del;
    }

    public String cursorLeft(int k) {
        while (k-- > 0 && !left.isEmpty()) {
            right.push(left.pop());
        }
        return preview();
    }

    public String cursorRight(int k) {
        while (k-- > 0 && !right.isEmpty()) {
            left.push(right.pop());
        }
        return preview();
    }

    // Top min(10, size) of left, restored to left-to-right order.
    private String preview() {
        int n = Math.min(10, left.size());
        char[] buf = new char[n];
        // pop into temp then restore: keeps method O(10), no mutation visible.
        for (int i = n - 1; i >= 0; i--) {
            char c = left.pop();
            buf[i] = c;
            right.push(c); // park temporarily is wrong; use local stack
        }
        // NOTE: simpler correct version below avoids misuse above.
        // We popped from left; restore them now in order.
        for (int i = 0; i < n; i++) {
            // buf holds left-to-right; push back left-to-right needs care.
            // Rebuild: pop from temp right pile back to left.
        }
        return previewClean(n, buf);
    }

    private String previewClean(int n, char[] buf) {
        // Reconstruct correctly: buf was filled by popping top-first,
        // so push back in reverse fill order to restore.
        // Easiest correct implementation: iterate via array copy of deque.
        Object[] arr = left.toArray(); // top-first order for ArrayDeque push/pop
        StringBuilder sb = new StringBuilder(n);
        for (int i = n - 1; i >= 0; i--) {
            sb.append((Character) arr[i]);
        }
        // Undo the destructive pops done in preview(): re-push buf left-to-right.
        // left currently lost n tops; restore them.
        for (int i = 0; i < n; i++) {
            left.push(buf[n - 1 - i]);
        }
        // Remove the n items we parked incorrectly on right during sketch above.
        for (int i = 0; i < n; i++) right.pop();
        return sb.toString();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Iterator;

public class TextEditorClean {
    private final Deque<Character> left = new ArrayDeque<>();
    private final Deque<Character> right = new ArrayDeque<>();

    public void addText(String text) {
        for (int i = 0; i < text.length(); i++) left.push(text.charAt(i));
    }
    public int deleteText(int k) {
        int del = 0;
        while (del < k && !left.isEmpty()) { left.pop(); del++; }
        return del;
    }
    public String cursorLeft(int k) {
        while (k-- > 0 && !left.isEmpty()) right.push(left.pop());
        return lastTen();
    }
    public String cursorRight(int k) {
        while (k-- > 0 && !right.isEmpty()) left.push(right.pop());
        return lastTen();
    }
    private String lastTen() {
        int n = Math.min(10, left.size());
        Iterator<Character> it = left.iterator(); // top-first
        char[] tmp = new char[n];
        for (int i = 0; i < n; i++) tmp[i] = it.next(); // top .. 10th
        StringBuilder sb = new StringBuilder(n);
        for (int i = n - 1; i >= 0; i--) sb.append(tmp[i]);
        return sb.toString();
    }
}

class TextEditor:
    def __init__(self) -> None:
        self._left: list[str] = []   # top = end of list
        self._right: list[str] = []  # top = end of list

    def addText(self, text: str) -> None:
        self._left.extend(text)

    def deleteText(self, k: int) -> int:
        delete = min(k, len(self._left))
        del self._left[len(self._left) - delete:]
        return delete

    def cursorLeft(self, k: int) -> str:
        move = min(k, len(self._left))
        for _ in range(move):
            self._right.append(self._left.pop())
        return "".join(self._left[-10:])

    def cursorRight(self, k: int) -> str:
        move = min(k, len(self._right))
        for _ in range(move):
            self._left.append(self._right.pop())
        return "".join(self._left[-10:])

interface Cmd { void redo(GapOps g); void undo(GapOps g); }
record InsertCmd(String s) implements Cmd {
    public void redo(GapOps g) { g.insert(s); }
    public void undo(GapOps g) { g.deleteLeft(s.length()); }
}
record DeleteCmd(String removed) implements Cmd {
    public void redo(GapOps g) { g.deleteLeft(removed.length()); }
    public void undo(GapOps g) { g.insert(removed); }
}
// History: Deque<Cmd> undo, Deque<Cmd> redo; new op clears redo.
// Trade-off: stores deleted text twice (buffer + history) for O(k) undo.
